=item * C<SCALING_MODE_UNSPECIFIED> => C<0>

=item * C<AUTOSCALE_ONLY> => C<1>

=item * C<IDLE_SLOTS_ONLY> => C<2>

=item * C<ALL_SLOTS> => C<3>

=back

=head2 Google::Cloud::Bigquery::Reservation::V1::Reservation::SchedulingPolicy

