=item * C<< $msg->concurrency() >> / C<< $msg->concurrency($value) >>

Type: C<Int64>

Optional. If present and > 0, the reservation will attempt to limit the
concurrency of jobs running for any particular project within it to the
given value.

This feature is not yet generally available.

=item * C<< $msg->max_slots() >> / C<< $msg->max_slots($value) >>

Type: C<Int64>

Optional. If present and > 0, the reservation will attempt to limit the
slot consumption of queries running for any particular project within it to
the given value.

This feature is not yet generally available.

=back

=head2 Google::Cloud::Bigquery::Reservation::V1::Reservation::ReservationGroup

A reservation group is a container for reservations.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The resource name of the reservation group, e.g.,
`projects/*/locations/*/reservationGroups/team1-prod`.
The reservation_group_id must only contain lower case alphanumeric
characters or dashes. It must start with a letter and must not end with a
dash. Its maximum length is 64 characters.

=item * C<< $msg->parent_group() >> / C<< $msg->parent_group($value) >>

Type: C<String>

Optional. The parent reservation group of the reservation group.
Format: `projects/*/locations/*/reservationGroups/team1-prod` for non-root
reservation groups, or `projects/*/locations/*` for root reservation
groups.

=item * C<< $msg->creation_time() >> / C<< $msg->creation_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Creation time of the reservation group.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Last update time of the reservation group via a user
operation. This timestamp is updated only when an update operation
explicitly targets this reservation group directly. It is not updated when
parent or child groups are created, updated, or deleted.

=back

=head2 Google::Cloud::Bigquery::Reservation::V1::Reservation::CapacityCommitment

Capacity commitment is a way to purchase compute capacity for BigQuery jobs
(in the form of slots) with some committed period of usage. Annual
commitments renew by default. Commitments can be removed after their
commitment end time passes.

In order to remove annual commitment, its plan needs to be changed
to monthly or flex first.

A capacity commitment resource exists as a child resource of the admin
project.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The resource name of the capacity commitment, e.g.,
`projects/myproject/locations/US/capacityCommitments/123`
The commitment_id must only contain lower case alphanumeric characters or
dashes. It must start with a letter and must not end
with a dash. Its maximum length is 64 characters.

=item * C<< $msg->slot_count() >> / C<< $msg->slot_count($value) >>

Type: C<Int64>

Optional. Number of slots in this commitment.

=item * C<< $msg->plan() >> / C<< $msg->plan($value) >>

Type: C<Enum> (L<Google::Cloud::Bigquery::Reservation::V1::CapacityCommitment::CommitmentPlan>)

Optional. Capacity commitment commitment plan.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Bigquery::Reservation::V1::CapacityCommitment::State>)

Output only. State of the commitment.

=item * C<< $msg->commitment_start_time() >> / C<< $msg->commitment_start_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The start of the current commitment period. It is applicable
only for ACTIVE capacity commitments. Note after the commitment is renewed,
commitment_start_time won't be changed. It refers to the start time of the
original commitment.

=item * C<< $msg->commitment_end_time() >> / C<< $msg->commitment_end_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The end of the current commitment period. It is applicable
only for ACTIVE capacity commitments. Note after renewal,
commitment_end_time is the time the renewed commitment expires. So itwould
be at a time after commitment_start_time + committed period, because we
don't change commitment_start_time ,

=item * C<< $msg->failure_status() >> / C<< $msg->failure_status($value) >>

Type: C<Message> (L<Google::Rpc::Status::Status>)

Output only. For FAILED commitment plan, provides the reason of failure.

=item * C<< $msg->renewal_plan() >> / C<< $msg->renewal_plan($value) >>

Type: C<Enum> (L<Google::Cloud::Bigquery::Reservation::V1::CapacityCommitment::CommitmentPlan>)

Optional. The plan this capacity commitment is converted to after
commitment_end_time passes. Once the plan is changed, committed period is
extended according to commitment plan. Only applicable for ANNUAL and TRIAL
commitments.

=item * C<< $msg->multi_region_auxiliary() >> / C<< $msg->multi_region_auxiliary($value) >>

Type: C<Bool>

Applicable only for commitments located within one of the BigQuery
multi-regions (US or EU).

If set to true, this commitment is placed in the organization's
secondary region which is designated for disaster recovery purposes.
If false, this commitment is placed in the organization's default region.

NOTE: this is a preview feature. Project must be allow-listed in order to
set this field.

=item * C<< $msg->edition() >> / C<< $msg->edition($value) >>

Type: C<Enum> (L<Google::Cloud::Bigquery::Reservation::V1::Edition>)

Optional. Edition of the capacity commitment.

=item * C<< $msg->is_flat_rate() >> / C<< $msg->is_flat_rate($value) >>

Type: C<Bool>

Output only. If true, the commitment is a flat-rate commitment, otherwise,
it's an edition commitment.

=back

=head3 Enum: CapacityCommitment::CommitmentPlan

=over 4

=item * C<COMMITMENT_PLAN_UNSPECIFIED> => C<0>

=item * C<FLEX> => C<3>

=item * C<FLEX_FLAT_RATE> => C<7>

=item * C<TRIAL> => C<5>

=item * C<MONTHLY> => C<2>

=item * C<MONTHLY_FLAT_RATE> => C<8>

=item * C<ANNUAL> => C<4>

=item * C<ANNUAL_FLAT_RATE> => C<9>

=item * C<THREE_YEAR> => C<10>

=item * C<NONE> => C<6>

=back

=head3 Enum: CapacityCommitment::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<PENDING> => C<1>

=item * C<ACTIVE> => C<2>

=item * C<FAILED> => C<3>

=back

